insert into public.products(id,slug,name,category,description,price_kobo,stock,color,cover_label,subtitle,specs) values
('10000000-0000-4000-8000-000000000001','daybook','The Daybook','Notebooks','An A5 ruled notebook for daily notes, meeting ideas, and thoughts you want to keep. A cloth-style cover and ribbon marker keep it simple.',850000,30,'#284f81','daybook','Space for every thought',ARRAY['A5 · 148 × 210 mm','192 ruled pages','100 gsm ivory paper','Ribbon page marker']),
('10000000-0000-4000-8000-000000000002','weekender','The Weekender','Planners','An undated weekly planner with room for priorities, appointments, and a few good intentions. Start whenever you are ready; no wasted dated pages.',1200000,25,'#8eb1c0','weekender','A little room to plan',ARRAY['A5 · 148 × 210 mm','52 undated weekly spreads','100 gsm ivory paper','Weekly priorities and notes']),
('10000000-0000-4000-8000-000000000003','pocket-notes','Pocket Notes','Notebooks','A compact notebook for lists, sketches, and ideas on the move. Small enough for a pocket or everyday bag, with plain pages for whatever arrives.',450000,40,'#d3bda2','pocket notes','Good ideas travel light',ARRAY['A6 · 105 × 148 mm','96 plain pages','90 gsm ivory paper','Flexible cover']),
('10000000-0000-4000-8000-000000000004','blue-hour','The Blue Hour','Notebooks','A dot-grid notebook for sketches, diagrams, bullet journals, and plans that do not fit between the lines. Quiet blue on the outside, open possibilities within.',950000,20,'#203349','blue hour','Your next blank canvas',ARRAY['A5 · 148 × 210 mm','192 dot-grid pages','100 gsm ivory paper','Elastic closure']),
('10000000-0000-4000-8000-000000000005','daily-pages','Daily Pages','Planners','A focused daily planner for your three priorities, schedule, and loose ends. Undated pages let you pick it up when you need a little more structure.',1050000,25,'#75948c','daily pages','One day at a time',ARRAY['A5 · 148 × 210 mm','120 undated daily pages','100 gsm ivory paper','Priority and schedule sections']),
('10000000-0000-4000-8000-000000000006','desk-duo','The Desk Duo','Sets','A Daybook and Pocket Notes together: one for the desk, one for the road. A practical two-notebook set for keeping your ideas close.',1600000,15,'#4b6f9b','desk duo','A thoughtful pair',ARRAY['One A5 ruled Daybook','One A6 plain Pocket Notes','192 + 96 pages','Paper band packaging']);